// Bare-metal benchmark: the Triton tutorial matmul compiled by PIton, run on
// all 12 QPUs of a Pi Zero / Pi 1, against the ARM1176 CPU on the same inputs.
//
// CPU baselines (caches on, -O3, hardware VFP): a straightforward i-k-j loop, a
// blocked SGEMM (packed panels, 4x4 register-blocked micro-kernel) in C, and the
// same with an assembly micro-kernel in VFP short-vector mode.
#include "rpi.h"
#include "piton_rt.h"
#include "matmul.h"          // generated by `make` (piton.tools.compile)
#include "arm_sgemm.h"

#ifndef MM
#define MM 256
#endif
#define BM 8
#define BN 64

// ARM-side copies of the inputs (ordinary cached RAM) and results
static float armA[MM * MM_K], armB[MM_K * MM], armC[MM * MM], armCv[MM * MM], armCn[MM * MM];
static float packA[MM * ARM_KC + 8], packB[ARM_KC * ARM_NC + 8];    // (+8: kernel reads ahead)

static uint32_t best_of(int reps, void (*run)(void)) {
    uint32_t best = ~0u;
    for (int r = 0; r < reps; r++) {
        uint32_t t0 = timer_get_usec();
        run();
        uint32_t t = timer_get_usec() - t0;
        if (t < best)
            best = t;
    }
    return best;
}

static void run_blocked(void) { arm_matmul_blocked(armA, armB, armC, MM, MM, MM_K, packA, packB, 0); }
static void run_vector(void) { arm_matmul_blocked(armA, armB, armCv, MM, MM, MM_K, packA, packB, 1); }
static void run_naive(void) { arm_matmul_naive(armA, armB, armCn, MM, MM, MM_K); }

static float absf(float x) { return x < 0 ? -x : x; }

// max |x - ref| / max |ref|; NaN anywhere makes it NaN (fails the check)
static float max_rel_diff(volatile float *x, const float *ref, int n) {
    float scale = 0, worst = 0;
    for (int i = 0; i < n; i++)
        if (!(absf(ref[i]) <= scale))
            scale = absf(ref[i]);
    for (int i = 0; i < n; i++) {
        float d = absf(x[i] - ref[i]);
        if (!(d <= worst))
            worst = d;
    }
    return worst / scale;
}

#define REPS 3

void notmain(void) {
    const int M = MM, N = MM, K = MM_K;
    float flop = 2.0f * (float)M * (float)N * (float)K;
    piton_init();
    printk("PIton matmul: %dx%dx%d on %d QPUs\n", M, N, K, piton_qpu_count());
    // clocks and memory split as the firmware set them (config.txt)
    static const uint32_t ids[4] = {PITON_CLOCK_ARM, PITON_CLOCK_CORE, PITON_CLOCK_V3D, PITON_CLOCK_SDRAM};
    static const char *names[4] = {"arm", "core", "v3d", "sdram"};
    uint32_t mhz_fw[4];
    for (int i = 0; i < 4; i++) {
        mhz_fw[i] = piton_clock_hz(ids[i], 0) / 1000000;
        printk("clock %s: %d MHz (firmware max %d MHz)\n", names[i], mhz_fw[i],
               piton_clock_hz(ids[i], 1) / 1000000);
    }
    uint32_t arm_mem, vc_base, vc_size;
    piton_memory_split(&arm_mem, &vc_base, &vc_size);
    printk("memory: ARM %d MB, GPU %d MB at %x\n", arm_mem >> 20, vc_size >> 20, vc_base);

    piton_buf_t a = piton_alloc(4 * M * K), b = piton_alloc(4 * K * N), c = piton_alloc(4 * M * N);
    volatile float *A = a.cpu, *B = b.cpu, *C = c.cpu;
    uint32_t s1 = 12345, s2 = 67890;
    for (int i = 0; i < M * K; i++)
        armA[i] = A[i] = piton_lcg_float(&s1);
    for (int i = 0; i < K * N; i++)
        armB[i] = B[i] = piton_lcg_float(&s2);
    for (int i = 0; i < M * N; i++)          // NaN: a kernel that skips a tile fails the check
        ((volatile uint32_t *)C)[i] = 0x7fc00000;

    // QPU (all GPU / mailbox work happens before the ARM caches are turned on).
    // `call` is the whole matmul_launch(): writing each program's uniforms,
    // clearing the GPU caches, queueing and waiting; `kernel` is from the first
    // queued program to the last one finishing.
    matmul_args_t args = {
        .a_ptr = a.bus, .b_ptr = b.bus, .c_ptr = c.bus,
        .M = M, .N = N, .stride_am = K, .stride_bk = N, .stride_cm = N,
    };
    unsigned grid = ((M + BM - 1) / BM) * ((N + BN - 1) / BN);
    uint32_t qpu = ~0u, qpu_call = ~0u;
    for (int r = 0; r < REPS; r++) {
        uint32_t t0 = timer_get_usec();
        uint32_t t = matmul_launch(&args, grid, 1, 1);
        uint32_t tc = timer_get_usec() - t0;
        if (t < qpu)
            qpu = t;
        if (tc < qpu_call)
            qpu_call = tc;
    }
    printk("QPU: best call %d us (kernel %d us) -> %f GFLOPS\n", qpu_call, qpu,
           flop / (float)qpu_call / 1000.0f);

    // ARM
    arm_caches_on();
    uint32_t mhz = arm_clock_mhz();
#ifdef KERNEL_BENCH
    {   // micro-kernel alone, panels and C tile in L1
        void arm_kernel4x4_vec(const float *ap, const float *bp, float *c, int ldc_bytes, int kc);
        static float ct[16];
        for (int kc = 16; kc <= 256; kc *= 4) {
            uint32_t t0 = timer_get_usec();
            for (int r = 0; r < 20000; r++)
                arm_kernel4x4_vec(armA, armB, ct, 16, kc);
            uint32_t t = timer_get_usec() - t0;
            printk("kernel kc=%d: %f GFLOPS in L1\n", kc, 2.0f * 16.0f * (float)kc * 20000.0f / (float)t / 1000.0f);
        }
    }
#endif
    uint32_t blocked = best_of(REPS, run_blocked);
    printk("ARM blocked C:      %d us -> %f GFLOPS\n", blocked, flop / (float)blocked / 1000.0f);
    uint32_t vector = best_of(REPS, run_vector);
    printk("ARM blocked vector: %d us -> %f GFLOPS\n", vector, flop / (float)vector / 1000.0f);
    uint32_t naive = best_of(MM <= 256 ? REPS : 1, run_naive);    // (reference only: ~1 min at 1024)
    printk("ARM naive:          %d us -> %f GFLOPS\n", naive, flop / (float)naive / 1000.0f);

    // results: QPU (round toward zero) and the other ARM versions against blocked C
    float e_qpu = max_rel_diff(C, armC, M * N);
    float e_vec = max_rel_diff((volatile float *)armCv, armC, M * N);
    float e_naive = max_rel_diff((volatile float *)armCn, armC, M * N);
    arm_caches_off();

    float peak = 2.0f * (float)mhz / 1000.0f;     // VFP11: 1 single multiply-accumulate / cycle
    printk("ARM clock %d MHz (PMU); ARM VFP peak %f GFLOPS\n", mhz, peak);
    uint32_t best_arm = vector < blocked ? vector : blocked;
    printk("speedup (QPU call time): %f x over the best ARM version, %f x over the ARM peak, "
           "%f x over naive ARM\n", (float)best_arm / (float)qpu_call,
           flop / (float)qpu_call / 1000.0f / peak, (float)naive / (float)qpu_call);
    printk("max |C - C_arm| / max |C_arm|: QPU %f, vector %f, naive %f\n", e_qpu, e_vec, e_naive);
    printk("RESULT mm=%d bk=%d qpu_call_us=%d qpu_kernel_us=%d arm_blocked_us=%d arm_vector_us=%d "
           "arm_naive_us=%d arm_mhz=%d core_mhz=%d v3d_mhz=%d sdram_mhz=%d\n",
           MM, BK, qpu_call, qpu, blocked, vector, naive, mhz, mhz_fw[1], mhz_fw[2], mhz_fw[3]);
    printk(e_qpu < 1e-4f && e_vec < 1e-4f && e_naive < 1e-4f ? "CHECK OK\n" : "CHECK FAILED\n");
}
